"""Pure, bounded traditional-to-simplified folding for metadata matching.

The embedded table is the compact character-level subset used only for lookup
normalization.  It never changes stored Tags or values returned to the UI.
"""

from __future__ import annotations

import base64
import functools
import zlib

_TABLE_B64 = ""
_MAX_INPUT_CHARS = 1024


@functools.lru_cache(maxsize=1)
def _traditional_to_simplified_table():
    raw = zlib.decompress(base64.b64decode(_TABLE_B64)).decode("utf-8")
    table = {}
    for line in raw.splitlines():
        source, separator, targets = line.partition("\t")
        if not separator or len(source) != 1 or not targets:
            continue
        target = targets.split(" ", 1)[0]
        if target:
            table[source] = target
    return table


def fold_han_variants(value):
    """Return text with traditional Han characters folded for matching only."""
    if not isinstance(value, str):
        return ""
    if len(value) > _MAX_INPUT_CHARS:
        value = value[:_MAX_INPUT_CHARS]
    if not value:
        return ""
    table = _traditional_to_simplified_table()
    return "".join(table.get(char, char) for char in value)


__all__ = ["fold_han_variants"]

